INSERT INTO serverless_stable_swv01_catalog.trb.meetings (meeting_id, meeting_date, meeting_type, meeting_location, attendees, quorum_met, meeting_notes, minutes_url, created_at) VALUES
  ('TRBM-2026-04-21', DATE '2026-04-21', 'hybrid', 'Boardroom A / video', 'CISO,Chief Privacy Officer,Enterprise Architect,Platform Engineering Lead,Data Governance Lead,Compliance Officer', TRUE, 'Decided: Secure Cluster Connectivity (NPIP) (Approved); PrivateLink (front-end & back-end) (Approved); Customer-managed keys (CMK) (Approved); Compliance security profile (Approved).', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/MIN-TRBM-2026-04-21.md', current_timestamp()),
  ('TRBM-2026-05-05', DATE '2026-05-05', 'hybrid', 'Boardroom A / video', 'CISO,Chief Privacy Officer,Enterprise Architect,Platform Engineering Lead,Data Governance Lead,Compliance Officer', TRUE, 'Decided: Unity Catalog (Approved); Audit logs (Approved); SSO / SCIM (Approved).', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/MIN-TRBM-2026-05-05.md', current_timestamp()),
  ('TRBM-2026-05-19', DATE '2026-05-19', 'hybrid', 'Boardroom A / video', 'CISO,Chief Privacy Officer,Enterprise Architect,Platform Engineering Lead,Data Governance Lead,Compliance Officer', TRUE, 'Decided: HIPAA (Approved); Enhanced Security Monitoring (Approved); Databricks CLI (Approved); Asset Bundles (DABs) (Approved).', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/MIN-TRBM-2026-05-19.md', current_timestamp()),
  ('TRBM-2026-06-02', DATE '2026-06-02', 'hybrid', 'Boardroom A / video', 'CISO,Chief Privacy Officer,Enterprise Architect,Platform Engineering Lead,Data Governance Lead,Compliance Officer', TRUE, 'Decided: Auto Loader (Approved); Lakeflow Declarative Pipelines (DLT) (Approved); Lakeflow Jobs (Workflows) (Approved).', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/MIN-TRBM-2026-06-02.md', current_timestamp()),
  ('TRBM-2026-06-16', DATE '2026-06-16', 'hybrid', 'Boardroom A / video', 'CISO,Chief Privacy Officer,Enterprise Architect,Platform Engineering Lead,Data Governance Lead,Compliance Officer', TRUE, 'Decided: Delta Lake (Approved); Databricks SQL (Approved); AI/BI Dashboards (Approved); MLflow (Approved); Serverless compute (Approved with Conditions).', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/MIN-TRBM-2026-06-16.md', current_timestamp()),
  ('TRBM-2026-06-30', DATE '2026-06-30', 'hybrid', 'Boardroom A / video', 'CISO,Chief Privacy Officer,Enterprise Architect,Platform Engineering Lead,Data Governance Lead,Compliance Officer', TRUE, 'Decided: Classic compute (Approved).', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/MIN-TRBM-2026-06-30.md', current_timestamp()),
  ('TRBM-2026-10-06', DATE '2026-10-06', 'hybrid', 'Boardroom A / video', 'CISO,Chief Privacy Officer,Enterprise Architect,Platform Engineering Lead,Data Governance Lead,Compliance Officer', TRUE, 'Introduced (Under Review): Salesforce, Lakebase (Postgres OLTP), AI/BI Genie, Model Serving, AI Functions (SQL), Clean Rooms.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/MIN-TRBM-2026-10-06.md', current_timestamp());
INSERT INTO serverless_stable_swv01_catalog.trb.reviews (review_id, feature_key, feature_name, domain, dbx_phase_at_decision, current_trb_status, approved_scope, initial_submission_date, latest_review_date, decision_date, primary_reviewer_role, approval_meeting_id, rereview_trigger, next_review_date, requesting_business_unit, use_cases, review_context, identified_risks, mitigations, open_issue_count, closed_issue_count, created_at, updated_at, decision_rationale, open_questions) VALUES
  ('TRB-2026-010', 'Unity Catalog@Platform & Governance', 'Unity Catalog', 'Platform & Governance', 'GA', 'Approved', 'PHI', DATE '2026-04-16', DATE '2026-05-05', DATE '2026-05-05', 'Data Governance Lead', 'TRBM-2026-05-05', 'Annual re-review', DATE '2027-05-05', 'Enterprise Data Platform', array('Enterprise governance', 'Cross-workspace lineage', 'Unified access control'), 'Enterprise Data Platform submitted UC as the foundational governance layer for the lakehouse. The TRB evaluated whether the metastore design and cross-region limitations meet the payer''s multi-workspace governance model.', 'Metastore region lock-in limits disaster recovery; Cross-catalog access complexity; Admin burden for large permission matrices', 'Delta Sharing used for cross-region workloads; Governance Hub provides centralized policy console; Role-based access templates for common personas', 0, 0, current_timestamp(), current_timestamp(), 'UC is approved as the payer''s single governance layer over all catalogs and PHI. The metastore region limitation is accepted as tolerable; cross-region PHI access will use Delta Sharing with explicit approvals.', ''),
  ('TRB-2026-011', 'Audit logs@Platform & Governance', 'Audit logs', 'Platform & Governance', 'GA', 'Approved', 'PHI', DATE '2026-04-18', DATE '2026-05-05', DATE '2026-05-05', 'CISO', 'TRBM-2026-05-05', 'Annual re-review or regulatory change', DATE '2027-05-05', 'Information Security', array('Audit trail for compliance', 'Breach-impact investigations', 'User activity tracking'), 'Information Security presented UC audit logs as the immutable evidence source for HIPAA and SOC 2 audits. Retention, tamper-proof storage, and query performance were evaluated.', 'Log volume for high-scale environments; Query complexity for forensics; Long-term retention cost', 'Audit logs stored in managed UC tables with VACUUM restrictions; System tables provide efficient log queries; Tiered retention policy: hot 90 days, cold 7 years', 0, 0, current_timestamp(), current_timestamp(), 'Audit logs are approved as the payer''s audit source. Retention follows the enterprise records-retention policy (7 years), implemented by the platform team through audit-log delivery and system-table exports; all production workspaces must deliver audit logs.', ''),
  ('TRB-2026-012', 'Salesforce@Ingestion', 'Salesforce', 'Ingestion', 'GA', 'Under Review', 'None', DATE '2026-09-17', DATE '2026-10-06', NULL, 'Chief Privacy Officer', NULL, 'OAuth scope change or new use case', DATE '2026-10-20', 'Member Experience', array('Member 360 golden record', 'Care team CRM sync', 'Case management analytics'), 'Member Experience submitted the Salesforce connector (Lakeflow Connect) to sync Health Cloud and Service Cloud member and case data for a 360-degree member view. TRB is reviewing OAuth scope and PII field mapping to ensure minimum-necessary extraction.', 'Overly broad OAuth scope pulls unnecessary PII; Case comments may contain sensitive clinical notes; CRM deletion/archival timing vs. lakehouse retention', 'OAuth scopes limited to standard Health Cloud objects; PII field mapping reviewed per data dictionary; Case comment fields excluded from initial sync', 3, 0, current_timestamp(), current_timestamp(), 'Under review. TRB asked: (1) Confirm final OAuth scope matches minimum-necessary and is documented. (2) Provide sample of member records synced to validate PII filtering. (3) Define CRM deletion sync behavior to align with 7-year retention. Follow-up at 2026-10-20.', 'What is the final OAuth scope for member and case objects, and how does it match minimum-necessary?; Provide 10-row sample of member records to verify PII extraction boundaries.; How will Salesforce record deletions cascade to the lakehouse, and what retention period applies?'),
  ('TRB-2026-013', 'Auto Loader@Ingestion', 'Auto Loader', 'Ingestion', 'GA', 'Approved', 'PHI', DATE '2026-05-14', DATE '2026-06-02', DATE '2026-06-02', 'Platform Engineering Lead', 'TRBM-2026-06-02', 'Partner feed change or volume 10x increase', DATE '2027-06-02', 'Claims Operations', array('837 EDI claim incremental ingestion', 'Daily eligibility file drops', 'Recurring partner feeds'), 'Claims Operations selected Auto Loader for continuous 837 EDI claim ingest and daily eligibility feeds. TRB evaluated file discovery mechanisms and guaranteed delivery semantics.', 'File notification latency for high-volume drops; Directory listing scalability at 10M+ files; Duplicate handling edge cases', 'File notification mode used for high-volume feeds; Schema inference handles field additions automatically; Duplicate detection via file path and checksum', 0, 0, current_timestamp(), current_timestamp(), 'Auto Loader is approved as the standard incremental ingestion path for claims and eligibility. File notification mode is required for high-volume EDI drops; directory listing is acceptable for lower-volume feeds.', ''),
  ('TRB-2026-014', 'Lakeflow Declarative Pipelines (DLT)@Pipelines & Data Engineering', 'Lakeflow Declarative Pipelines (DLT)', 'Pipelines & Data Engineering', 'GA', 'Approved', 'PHI', DATE '2026-05-15', DATE '2026-06-02', DATE '2026-06-02', 'Platform Engineering Lead', 'TRBM-2026-06-02', 'Major DLT architecture change', DATE '2027-06-02', 'Claims Operations', array('Claims medallion curation', 'Quality expectations enforcement', 'Member identity matching'), 'Claims Operations proposed DLT as the standard for building medallion (bronze/silver/gold) pipelines. TRB reviewed data-quality expectations, SCD handling, and audit capabilities.', 'Expectation failures hide data-quality issues if quarantine not monitored; SCD Type 2 complexity for member history; Pipeline dependencies not visible in lineage', 'Expectations route bad rows to quarantine tables with alerts; APPLY CHANGES handles SCD Type 2 natively; DLT lineage integrates with UC governance hub', 0, 0, current_timestamp(), current_timestamp(), 'DLT is approved as the enterprise standard for building and curating trusted claims and member tables. Expectation failures must be monitored; quarantine tables are part of the standard architecture.', ''),
  ('TRB-2026-015', 'Lakeflow Jobs (Workflows)@Pipelines & Data Engineering', 'Lakeflow Jobs (Workflows)', 'Pipelines & Data Engineering', 'GA', 'Approved', 'PHI', DATE '2026-05-16', DATE '2026-06-02', DATE '2026-06-02', 'Enterprise Architect', 'TRBM-2026-06-02', 'Annual re-review', DATE '2027-06-02', 'Claims Operations', array('Daily claims processing orchestration', 'Multi-step reconciliation workflows', 'Reporting job scheduling'), 'Claims Operations and Finance jointly submitted Workflows (Lakeflow Jobs) as the enterprise orchestration engine. TRB evaluated task types, error handling, and audit logging.', 'Job dependencies not captured if manual coordination still used; Timeout handling for long-running claims joins; Audit trail for task-level retries', 'Job DAG enforces explicit task dependencies; Timeout limits configured per task type; Each task execution logged to audit tables', 0, 0, current_timestamp(), current_timestamp(), 'Workflows is approved as the enterprise standard for all scheduled and multi-step workloads. All production claims, eligibility, and reporting jobs must use Workflows.', ''),
  ('TRB-2026-016', 'Delta Lake@Storage & Formats', 'Delta Lake', 'Storage & Formats', 'GA', 'Approved', 'PHI', DATE '2026-05-28', DATE '2026-06-16', DATE '2026-06-16', 'Enterprise Architect', 'TRBM-2026-06-16', 'Annual re-review', DATE '2027-06-16', 'Enterprise Data Platform', array('All claims and member storage', 'Time travel for audit and recovery', 'ACID upserts for incremental updates'), 'Enterprise Data Platform designated Delta as the default table format for all PHI workloads. TRB reviewed ACID guarantees, time-travel retention, and interoperability.', 'Time-travel retention increases storage cost; Format lock-in vs. open formats; Upgrade complexity for large tables', 'VACUUM policy: 180-day retention for PHI, 30 days for analytics; Iceberg interoperability via UniForm; Delta version checks automated in CI/CD', 0, 0, current_timestamp(), current_timestamp(), 'Delta Lake is approved as the default table format. All new tables use Delta unless approved for Iceberg. Time-travel and VACUUM retention are set per table to meet the records-retention policy.', ''),
  ('TRB-2026-017', 'Lakebase (Postgres OLTP)@Storage & Formats', 'Lakebase (Postgres OLTP)', 'Storage & Formats', 'GA', 'Under Review', 'None', DATE '2026-09-19', DATE '2026-10-06', NULL, 'Chief Privacy Officer', NULL, 'Backup policy change or new retention requirement', DATE '2026-10-27', 'Member Experience', array('Member portal app backing store', 'Low-latency care-team reference data', 'Operational app transactions'), 'Member Experience submitted Lakebase (managed Postgres OLTP) for powering member-facing apps with low-latency serving next to the lakehouse. TRB is reviewing backup/recovery, retention, and PHI-at-rest encryption.', 'Automatic backups may retain deleted PHI; Retention policy not aligned to HIPAA 6-year minimum; CMK coverage for Postgres storage', 'Backup retention tuned to 7-year hold period; Automated backup lifecycle per retention policy; CMK applied to all Postgres instances', 3, 0, current_timestamp(), current_timestamp(), 'Under review. TRB asked: (1) Confirm backup retention policy covers 7 years for regulated data. (2) Verify CMK encryption covers Postgres storage at rest. (3) Provide recovery RTO/RPO guarantees. Follow-up at 2026-10-27.', 'What is the backup retention policy for Lakebase instances handling PHI, and how is it enforced?; Does CMK encryption cover Postgres storage at rest, and how is key rotation managed?; What are the recovery RTO and RPO guarantees for Postgres backups?'),
  ('TRB-2026-018', 'Databricks SQL@SQL & BI Analytics', 'Databricks SQL', 'SQL & BI Analytics', 'GA', 'Approved', 'PHI', DATE '2026-05-29', DATE '2026-06-16', DATE '2026-06-16', 'Data Governance Lead', 'TRBM-2026-06-16', 'Annual re-review', DATE '2027-06-16', 'Analytics Operations', array('BI tool connections (Tableau, Looker)', 'Ad-hoc analyst queries', 'Scheduled reporting SQL'), 'Analytics Operations selected Databricks SQL (serverless warehouse) as the serving layer for analysts and BI tools querying PHI. TRB reviewed row/column filter enforcement and audit logging.', 'Filters bypassed if analysts query storage directly; Warehouse concurrency limits at scale; Audit log volume for high-query-rate environments', 'External table access restricted; SQL warehouse required; Warehouse queues configured per team SLA; Audit sampling for cost control; 100% for PHI modifications', 0, 0, current_timestamp(), current_timestamp(), 'Databricks SQL is approved as the enterprise serving layer for BI and analytics. All BI tool connections must go through SQL warehouses. Row and column filters are enforced at query time.', ''),
  ('TRB-2026-019', 'AI/BI Dashboards@SQL & BI Analytics', 'AI/BI Dashboards', 'SQL & BI Analytics', 'GA', 'Approved', 'PHI', DATE '2026-05-30', DATE '2026-06-16', DATE '2026-06-16', 'Data Governance Lead', 'TRBM-2026-06-16', 'Annual re-review', DATE '2027-06-16', 'Analytics Operations', array('Executive dashboards with HEDIS/STARS metrics', 'Quality-measure tracking', 'Member cohort analysis'), 'Analytics Operations submitted AI/BI Dashboards for internal governance and reporting. TRB evaluated row/column filter enforcement in dashboards and viewer access controls.', 'Filters not reapplied after refresh; Viewer impersonation leaks cross-team data; Cache stale PHI', 'Filters re-evaluated on each refresh; Viewer access uses UC identities, no impersonation; Cache TTL set to 15 minutes for PHI dashboards', 0, 0, current_timestamp(), current_timestamp(), 'AI/BI Dashboards are approved for internal governance and reporting with PHI filters. Dashboards must be built on UC tables with row/column masks enabled.', ''),
  ('TRB-2026-020', 'AI/BI Genie@SQL & BI Analytics', 'AI/BI Genie', 'SQL & BI Analytics', 'GA', 'Under Review', 'None', DATE '2026-09-20', DATE '2026-10-06', NULL, 'Chief Privacy Officer', NULL, 'Genie architecture change or new foundation model', DATE '2026-10-25', 'Analytics Operations', array('Analyst self-serve Q&A over PHI', 'HEDIS/STARS metric queries', 'Ad-hoc member cohort analysis'), 'Analytics Operations submitted AI/BI Genie (natural-language Q&A) as an umbrella review for analyst self-serve access to PHI. Genie One (TRB-2026-005) is an existing approved use case. TRB is evaluating whether UC row/column masks and filters are proven to hold in Genie-generated SQL.', 'Generated SQL bypasses row/column filters; LLM prompt injection exposes schema or data; Genie answer cache leaks PHI between users', 'Genie SQL generation goes through UC masking validation; User prompt validation and sanitization before LLM; Query result cache isolated per user with TTL', 3, 0, current_timestamp(), current_timestamp(), 'Under review. TRB asked: (1) Provide proof that UC row/column masks are applied in Genie-generated SQL for 5 test queries. (2) Demonstrate prompt injection mitigation. (3) Confirm cache isolation. Genie One has its own review (TRB-2026-005, Approved with Conditions); this umbrella review covers broader AI/BI Genie agent use with PHI. Follow-up at 2026-10-25.', 'Provide test results showing UC row/column masks applied in Genie-generated SQL.; What prompt injection attacks have been tested and mitigated?; How is Genie query result cache isolated per user, and what is the TTL?'),
  ('TRB-2026-021', 'MLflow@AI / ML', 'MLflow', 'AI / ML', 'GA', 'Approved', 'PHI', DATE '2026-05-31', DATE '2026-06-16', DATE '2026-06-16', 'Platform Engineering Lead', 'TRBM-2026-06-16', 'Annual re-review', DATE '2027-06-16', 'Research & Innovation', array('Risk and readmission model training', 'Model versioning and governance', 'Production model promotion'), 'Research & Innovation selected MLflow as the system of record for ML model lifecycle (training, versioning, governance). TRB reviewed experiment tracking, parameter audit, and model promotion controls.', 'Training data lineage not captured; Model artifact storage not versioned; Parameter drift across training runs', 'MLflow experiments linked to UC tables via lineage; Model artifacts stored in UC volumes with versioning; Parameter comparison provided in MLflow UI', 0, 0, current_timestamp(), current_timestamp(), 'MLflow is approved as the enterprise model registry and lifecycle system. All trained models must be logged to MLflow; promotion to production requires model-card sign-off.', ''),
  ('TRB-2026-022', 'Model Serving@AI / ML', 'Model Serving', 'AI / ML', 'GA', 'Under Review', 'None', DATE '2026-09-21', DATE '2026-10-06', NULL, 'CISO', NULL, 'New model deployment or scoring use case', DATE '2026-10-23', 'Research & Innovation', array('Real-time risk scoring on incoming claims', 'Fraud detection APIs', 'Member eligibility real-time check'), 'Research & Innovation submitted Model Serving for deploying trained models as low-latency APIs (e.g., real-time risk scoring on claims). TRB is reviewing network isolation and audit logging before scoring PHI.', 'API endpoint exposed to internet without auth; Model input/output not logged for audit; Inference latency violates claims SLA', 'Model endpoints run in private network with VPC endpoint; Request/response logging to audit tables with sampling; P99 latency target: <100ms for risk scoring', 3, 0, current_timestamp(), current_timestamp(), 'Under review. TRB asked: (1) Confirm endpoints run in private network accessible only via VPC endpoint. (2) Demonstrate audit logging for inference requests. (3) Validate latency meets claims-processing SLA. Follow-up at 2026-10-23.', 'Are Model Serving endpoints restricted to private network access via VPC endpoint?; What inference request/response data is logged, and where is it stored?; What are the P50/P99 latency targets for risk-scoring APIs, and are they validated?'),
  ('TRB-2026-023', 'AI Functions (SQL)@Generative AI & Agents', 'AI Functions (SQL)', 'Generative AI & Agents', 'GA', 'Under Review', 'None', DATE '2026-09-22', DATE '2026-10-06', NULL, 'Chief Privacy Officer', NULL, 'New foundation model or use case', DATE '2026-10-24', 'Analytics Operations', array('Appeal letter classification and summarization', 'Diagnosis code extraction from clinical notes', 'Member sentiment from feedback surveys'), 'Analytics Operations submitted AI Functions (SQL) for calling foundation models directly from SQL to classify, extract, and summarize at scale. TRB is reviewing which foundation models are approved for PHI-bearing prompts.', 'LLM training data includes customer prompts and outputs; Uncontrolled model drift affects classification accuracy; Prompt injection reveals PII in classification result', 'Foundation models vetted for no-training-data-retention guarantees; Model versioning controlled via Databricks Foundation Model API; Input sanitization and prompt injection validation', 3, 0, current_timestamp(), current_timestamp(), 'Under review. TRB asked: (1) Which foundation models have been approved by Legal/Privacy for PHI? (2) Provide no-training-data-retention guarantee from model provider(s). (3) Demonstrate input sanitization for classification prompts. Follow-up at 2026-10-24.', 'Which foundation models (Anthropic, OpenAI, etc.) are approved for PHI-bearing prompts?; What is the no-training-data-retention guarantee from each approved provider?; What input sanitization is applied to prompts before sending to foundation models?'),
  ('TRB-2026-024', 'Clean Rooms@Sharing & Collaboration', 'Clean Rooms', 'Sharing & Collaboration', 'GA', 'Under Review', 'None', DATE '2026-09-23', DATE '2026-10-06', NULL, 'Chief Privacy Officer', NULL, 'New collaborator or use case change', DATE '2026-10-28', 'Provider Strategy', array('Payer-provider joint analytics (de-identified)', 'Network analysis without data exchange', 'Quality improvement collaborative projects'), 'Provider Strategy submitted Clean Rooms for joint analytics with provider networks where neither party exposes raw PHI. TRB is reviewing PHI handling in multi-party outputs and approval workflows.', 'De-identification logic insufficient for re-identification risk; Query results leak member-level PHI through aggregates; Collaborator dataset inadvertently contains PII', 'De-identification rules reviewed by Chief Privacy Officer per-engagement; Output tables limited to summary statistics (counts, rates); Collaborator dataset scan for PII before upload', 3, 0, current_timestamp(), current_timestamp(), 'Under review. TRB asked: (1) Define de-identification thresholds and sign-off process. (2) Provide sample output tables and risk assessment. (3) Confirm Clean Room approval workflow includes CPO review. Follow-up at 2026-10-28.', 'What de-identification thresholds and rules apply to Clean Room outputs?; Provide sample output tables and re-identification risk assessment.; What is the Clean Room approval workflow, and who must sign off?'),
  ('TRB-2026-025', 'Secure Cluster Connectivity (NPIP)@Security & Networking', 'Secure Cluster Connectivity (NPIP)', 'Security & Networking', 'GA', 'Approved', 'PHI', DATE '2026-04-02', DATE '2026-04-21', DATE '2026-04-21', 'CISO', 'TRBM-2026-04-21', 'Annual re-review', DATE '2027-04-21', 'Information Security', array('No-public-IP compute for PHI workloads', 'Network segmentation baseline', 'Reduced internet egress exposure'), 'Information Security presented Secure Cluster Connectivity (no-public-IP / NPIP) as a baseline network control for production PHI workloads. TRB reviewed routing and internet access constraints.', 'Public IPs still assigned if not configured correctly; Internet egress via NAT leaks IP source; Egress filtering not enforced', 'Cluster policies enforce no-public-IP setting; NAT gateway restricted to approved destinations; Egress firewall rules in network policies', 0, 0, current_timestamp(), current_timestamp(), 'Secure Cluster Connectivity is approved and required for all production PHI workloads. All production clusters must have public IPs disabled.', ''),
  ('TRB-2026-026', 'PrivateLink (front-end & back-end)@Security & Networking', 'PrivateLink (front-end & back-end)', 'Security & Networking', 'GA', 'Approved', 'PHI', DATE '2026-04-03', DATE '2026-04-21', DATE '2026-04-21', 'CISO', 'TRBM-2026-04-21', 'Annual re-review', DATE '2027-04-21', 'Information Security', array('Private control-plane connectivity to Databricks', 'Private data-plane traffic routing', 'Off-public-internet data residency'), 'Information Security proposed PrivateLink (AWS PrivateLink) for front-end and back-end connectivity, keeping all Databricks traffic off the public internet. TRB reviewed endpoint configuration and traffic isolation.', 'Front-end PrivateLink alone allows data egress via internet; Back-end PrivateLink adds cost and complexity; NAT gateway still needed for non-Databricks egress', 'Dual PrivateLink (front + back) required for PHI workloads; Network policies restrict back-end routing; NAT gateway egress filtered to approved destinations', 0, 0, current_timestamp(), current_timestamp(), 'PrivateLink is approved as a core requirement for the payer''s PHI environment. Dual PrivateLink (front and back) is required for production PHI. Single PrivateLink is acceptable for non-PHI analytics.', ''),
  ('TRB-2026-027', 'Customer-managed keys (CMK)@Security & Networking', 'Customer-managed keys (CMK)', 'Security & Networking', 'GA', 'Approved', 'PHI', DATE '2026-04-04', DATE '2026-04-21', DATE '2026-04-21', 'CISO', 'TRBM-2026-04-21', 'Annual re-review', DATE '2027-04-21', 'Information Security', array('Key ownership for regulated data', 'Encryption at rest with payer-controlled keys', 'Key rotation and revocation'), 'Information Security selected Customer-Managed Keys (CMK) for encrypting PHI at rest. TRB reviewed key lifecycle, HSM support, and key rotation automation.', 'Key loss disables all encrypted data; Rotation complexity for multi-region deployments; KMS authorization bypass', 'Keys backed up in AWS KMS secure vault; Automated rotation via KMS key policy; KMS access controlled via IAM + UC external locations', 0, 0, current_timestamp(), current_timestamp(), 'Customer-managed keys are approved and required for all PHI data at rest. Encryption must use CMK; AWS default keys are not acceptable for PHI.', ''),
  ('TRB-2026-028', 'Compliance security profile@Security & Networking', 'Compliance security profile', 'Security & Networking', 'GA', 'Approved', 'PHI', DATE '2026-04-05', DATE '2026-04-21', DATE '2026-04-21', 'Compliance Officer', 'TRBM-2026-04-21', 'Annual re-review', DATE '2027-04-21', 'Information Security', array('HIPAA posture for all PHI workloads', 'Hardened compute images', 'Enhanced monitoring and logging'), 'Information Security presented the Compliance Security Profile (CSP) as the master switch for HIPAA/PCI/FedRAMP posture. TRB reviewed hardened images, audit requirements, and permanent enablement.', 'Permanent CSP flag blocks certain features; Image updates may have performance impact; Audit logging volume increases cost', 'CSP feature matrix documented (limits known upfront); Performance impact quantified (<5% CPU overhead); Audit sampling tuned to balance cost vs. visibility', 0, 0, current_timestamp(), current_timestamp(), 'The Compliance Security Profile is approved and required for all PHI workloads. Once enabled on a workspace, it cannot be disabled. All production PHI workspaces must have CSP enabled.', ''),
  ('TRB-2026-029', 'HIPAA@Security & Networking', 'HIPAA', 'Security & Networking', 'GA', 'Approved', 'PHI', DATE '2026-05-08', DATE '2026-05-19', DATE '2026-05-19', 'Compliance Officer', 'TRBM-2026-05-19', 'Annual re-review or regulatory change', DATE '2027-05-19', 'Information Security', array('HIPAA-regulated data handling', 'Protected health information workloads', 'HIPAA audit and compliance reporting'), 'Compliance Officer submitted the HIPAA profile as the specific security and privacy posture for the payer''s regulated data. TRB reviewed controls mapping to 45 CFR 164 Privacy and Security Rules.', 'Controls incomplete for all HIPAA subparts; Breach notification workflow not in Databricks; Workforce training requirements outside platform', 'Controls matrix maps UC features to 45 CFR 164 controls; Breach procedures documented in payer playbook (out-of-band); SSO/SCIM enforces identity provider training compliance', 0, 0, current_timestamp(), current_timestamp(), 'The HIPAA profile is approved as the payer''s standard security and privacy posture for PHI. All PHI workspaces must enable the compliance security profile with the HIPAA compliance standard selected, under the signed BAA.', ''),
  ('TRB-2026-030', 'Enhanced Security Monitoring@Security & Networking', 'Enhanced Security Monitoring', 'Security & Networking', 'GA', 'Approved', 'PHI', DATE '2026-05-09', DATE '2026-05-19', DATE '2026-05-19', 'CISO', 'TRBM-2026-05-19', 'Annual re-review', DATE '2027-05-19', 'Information Security', array('Malware detection on compute', 'File integrity monitoring', 'Vulnerability scanning for patches'), 'Information Security selected Enhanced Security Monitoring (ESM) to add malware, file-integrity, and vulnerability monitoring on compute handling PHI. TRB reviewed agent overhead and alert handling.', 'Monitoring agent impacts cluster performance; False positives overwhelm security team; Classic-compute-only limitation', 'Agent overhead <5% CPU; tuned sampling rates; Alert thresholds and allowlists reduce false positives; Serverless compute ESM roadmap exists but not yet approved', 0, 0, current_timestamp(), current_timestamp(), 'Enhanced Security Monitoring is approved for production PHI workloads on classic compute. ESM is required for all production clusters running PHI. ESM coverage for serverless compute is to be confirmed with the account team.', ''),
  ('TRB-2026-031', 'SSO / SCIM@Security & Networking', 'SSO / SCIM', 'Security & Networking', 'GA', 'Approved', 'PHI', DATE '2026-04-17', DATE '2026-05-05', DATE '2026-05-05', 'CISO', 'TRBM-2026-05-05', 'Annual re-review', DATE '2027-05-05', 'Information Security', array('Centralized identity via IdP', 'Automatic user provisioning and deprovisioning', 'Single sign-on across Databricks'), 'Information Security proposed SSO and SCIM (via Okta) for centralized identity management and automatic deprovisioning. TRB reviewed IdP failover and access revocation timing.', 'SSO outage blocks Databricks access; SCIM sync lag delays deprovisioning; Local accounts bypass SSO controls', 'IdP redundancy via multiple Okta instances; SCIM sync runs every 15 minutes; max 15-min lag; Cluster policies forbid local user creation', 0, 0, current_timestamp(), current_timestamp(), 'SSO and SCIM are approved and required for enterprise access control. All users must authenticate via Okta SSO. Local accounts are prohibited for PHI workspaces.', ''),
  ('TRB-2026-032', 'Databricks CLI@Apps & Developer Tools', 'Databricks CLI', 'Apps & Developer Tools', 'GA', 'Approved', 'PHI', DATE '2026-05-10', DATE '2026-05-19', DATE '2026-05-19', 'Platform Engineering Lead', 'TRBM-2026-05-19', 'Annual re-review', DATE '2027-05-19', 'Enterprise Data Platform', array('Scriptable platform automation', 'This feature tracker weekly refresh job', 'Infrastructure-as-code tooling'), 'Enterprise Data Platform submitted Databricks CLI for automation and this tracker''s weekly refresh workflow. TRB reviewed credential handling and audit logging.', 'API token lifetime and rotation; CLI audit trail sparse vs. web console; Token compromise in CI/CD pipelines', 'API tokens limited to service principals with short TTL; CLI calls logged via audit tables; GitHub Actions tokens use temporary credentials', 0, 0, current_timestamp(), current_timestamp(), 'The Databricks CLI is approved for platform-team tooling and automation. CLI is restricted to service-principal identities. Human API tokens are discouraged.', ''),
  ('TRB-2026-033', 'Asset Bundles (DABs)@Apps & Developer Tools', 'Asset Bundles (DABs)', 'Apps & Developer Tools', 'GA', 'Approved', 'PHI', DATE '2026-05-11', DATE '2026-05-19', DATE '2026-05-19', 'Enterprise Architect', 'TRBM-2026-05-19', 'Annual re-review', DATE '2027-05-19', 'Enterprise Data Platform', array('Versioned job and pipeline deployment', 'Repeatable infrastructure-as-code releases', 'Audit trail of infrastructure changes'), 'Enterprise Data Platform selected Asset Bundles (DABs) as the enterprise deployment standard for jobs, pipelines, and apps. TRB reviewed version control integration and rollback procedures.', 'DAB validation doesn''t catch breaking changes; Rollback complexity for large bundles; Production deployment coordination', 'DAB syntax validation in pre-commit hooks; Automated rollback via Git revert; Deployment windows scheduled weekly', 0, 0, current_timestamp(), current_timestamp(), 'Asset Bundles are approved as the enterprise deployment standard. All production jobs and pipelines must be deployed via DABs. Manual resource creation is prohibited.', ''),
  ('TRB-2026-034', 'Serverless compute@Compute', 'Serverless compute', 'Compute', 'GA', 'Approved with Conditions', 'PHI (after all conditions close)', DATE '2026-05-27', DATE '2026-06-16', DATE '2026-06-16', 'Enterprise Architect', 'TRBM-2026-06-16', 'CSP on serverless GA or Compute strategy change', DATE '2026-08-16', 'Finance', array('Elastic batch processing for claims jobs', 'Cost optimization for bursty workloads', 'Instant compute for on-demand queries'), 'Finance selected Serverless Compute to reduce idle costs for bursty claims and reporting jobs. TRB is approving with conditions on compliance security profile validation and cost attribution.', 'Compliance security profile not available on serverless; Cost spikes from unlimited autoscaling; Multi-tenant noisy-neighbor performance', 'Compliance security profile roadmap confirms PHI support Q4 2026; Spend controls via serverless job capacity reservations; Isolated pools for high-priority workloads', 3, 0, current_timestamp(), current_timestamp(), 'Serverless Compute is approved with conditions. PHI workloads require the compliance security profile enabled before production use. Condition COND-034-1 requires CSP GA on serverless; COND-034-2 requires cost attribution implementation; COND-034-3 requires performance baseline. Follow-up at 2026-08-16.', ''),
  ('TRB-2026-035', 'Classic compute@Compute', 'Classic compute', 'Compute', 'GA', 'Approved', 'PHI', DATE '2026-06-10', DATE '2026-06-30', DATE '2026-06-30', 'Platform Engineering Lead', 'TRBM-2026-06-30', 'Annual re-review', DATE '2027-06-30', 'Enterprise Data Platform', array('Customer-managed clusters for specific workloads', 'Dedicated cluster pools for teams', 'GPU compute for ML training'), 'Enterprise Data Platform maintains Classic Compute as a strategic compute option for workloads requiring specific instance types or network controls not available via serverless.', 'Idle cluster cost drift; Cluster configuration drift vs. policy; Dependency on legacy cluster manager', 'Cluster auto-termination policies enforced; Cluster policies lock critical settings; Gradual migration to serverless as gaps close', 0, 0, current_timestamp(), current_timestamp(), 'Classic Compute is approved for production workloads where serverless is not suitable. Cluster policies are required; all production clusters must use an approved Databricks Runtime LTS version, with Photon where supported.', '');
INSERT INTO serverless_stable_swv01_catalog.trb.approval_conditions (condition_id, review_id, condition_number, condition_title, condition_text, condition_rationale, applicable_at_phase, verification_method, verification_status, verification_date, verified_by_role, verification_notes, created_at, updated_at, due_date) VALUES
  ('COND-034-1', 'TRB-2026-034', 1, 'Compliance Security Profile (CSP) GA on Serverless', 'Databricks must release CSP support for serverless compute. PHI workloads are blocked until CSP is GA and validated on serverless.', 'PHI workloads require CSP hardening; CSP is not yet available on serverless.', 'GA', 'Databricks product release notes and feature availability documentation', 'Open', NULL, NULL, NULL, current_timestamp(), current_timestamp(), DATE '2026-12-31'),
  ('COND-034-2', 'TRB-2026-034', 2, 'Cost Attribution to Claims Operations', 'Implement cost allocation for serverless jobs so Claims Operations can track DBU spend. Tagging must enable per-job and per-team cost reporting.', 'Finance needs visibility into serverless costs to optimize and attribute to business units.', 'GA', 'Cost analysis report showing serverless job costs tagged by team and workload', 'In Progress', NULL, NULL, NULL, current_timestamp(), current_timestamp(), DATE '2026-08-16'),
  ('COND-034-3', 'TRB-2026-034', 3, 'Performance Baseline for Claims Jobs', 'Run 5 pilot claims jobs on serverless (100-500GB datasets) and document P50/P99 latency vs. classic compute. Startup overhead must be <5 min.', 'Claims processing SLAs require validated latency to ensure serverless meets production requirements.', 'GA', 'Performance benchmark report with job latency distributions and startup times', 'Open', NULL, NULL, NULL, current_timestamp(), current_timestamp(), DATE '2026-07-16');
