  ('CAL-TRB-2026-005', 'approval_letter', 'Conditional Approval Letter – Technical Review Board Decision', DATE '2026-07-29', NULL, '/Volumes/serverless_stable_swv01_catalog/trb/corpus/CAL-TRB-2026-005.md', array('TRB-2026-005'), current_timestamp(), 'Conditional approval letter for Genie One listing COND-005-1..4 with due dates and verification methods.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/CAL-TRB-2026-005.pdf'),
  ('CAL-TRB-2026-007', 'approval_letter', 'Conditional Approval Letter: Mode', DATE '2026-08-26', NULL, '/Volumes/serverless_stable_swv01_catalog/trb/corpus/CAL-TRB-2026-007.md', array('TRB-2026-007'), current_timestamp(), 'Conditional approval letter for Databricks-to-Open sharing listing COND-007-1..3.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/CAL-TRB-2026-007.pdf'),
  ('CAL-TRB-2026-034', 'approval_letter', 'Conditional Approval Letter: Serverless compute', DATE '2026-06-16', 'TRBM-2026-06-16', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/CAL-TRB-2026-034.md', array('TRB-2026-034'), current_timestamp(), 'Conditional approval letter for Serverless compute listing 3 conditions (COND-034-1..3); PHI use waits until all close.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/CAL-TRB-2026-034.pdf'),
  ('CHARTER-2026', 'charter', 'Technical Review Board (TRB) Charter – Acme Health Plan', DATE '2026-04-01', NULL, '/Volumes/serverless_stable_swv01_catalog/trb/corpus/CHARTER-2026.md', CAST(array() AS ARRAY<STRING>), current_timestamp(), 'TRB charter: membership, authority, quorum (4 members including CISO or CPO), biweekly cadence, review lifecycle, and the PHI rule (GA and Approved only). Effective 2026-04-01, revised 2026-07-01.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/CHARTER-2026.pdf'),
  ('DR-2026-001', 'decision_record', 'Decision Record: Approve Row Filters & Column Masks', DATE '2026-07-14', NULL, '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-001.md', array('TRB-2026-001'), current_timestamp(), 'Decision record: Row filters & column masks approved for PHI with no conditions.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-001.pdf'),
  ('DR-2026-003', 'decision_record', 'Decision Record: Approve SQL Server Connector (Non-PHI Only)', DATE '2026-07-14', NULL, '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-003.md', array('TRB-2026-003'), current_timestamp(), 'Decision record: SQL Server connector approved for non-PHI only while in Public Preview; conditions COND-003-1..2; re-review at GA.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-003.pdf'),
  ('DR-2026-004', 'decision_record', 'Decision Record: Reject Kafka Connector (Beta)', DATE '2026-07-14', NULL, '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-004.md', array('TRB-2026-004'), current_timestamp(), 'Decision record: Kafka-compatible APIs rejected. Beta is out of compliance scope; resubmit at GA.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-004.pdf'),
  ('DR-2026-005', 'decision_record', 'Architectural Decision Record (ADR) – TRB Decision: Genie One', DATE '2026-07-28', NULL, '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-005.md', array('TRB-2026-005'), current_timestamp(), 'Decision record: Genie One approved with conditions COND-005-1..4; not PHI-eligible until all close.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-005.pdf'),
  ('DR-2026-007', 'decision_record', 'Decision Record: Approve Mode with Conditions', DATE '2026-08-25', NULL, '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-007.md', array('TRB-2026-007'), current_timestamp(), 'Decision record: Databricks-to-Open sharing approved with conditions COND-007-1..3; non-PHI only until a recipient BAA is signed.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-007.pdf'),
  ('DR-2026-010', 'decision_record', 'Decision Record DR-2026-010: Unity Catalog', DATE '2026-05-05', 'TRBM-2026-05-05', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-010.md', array('TRB-2026-010'), current_timestamp(), 'Decision record: Unity Catalog approved (scope: PHI) at TRBM-2026-05-05. UC is approved as the payer''s single governance layer over all catalogs and PHI.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-010.pdf'),
  ('DR-2026-011', 'decision_record', 'Decision Record DR-2026-011: Audit logs', DATE '2026-05-05', 'TRBM-2026-05-05', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-011.md', array('TRB-2026-011'), current_timestamp(), 'Decision record: Audit logs approved (scope: PHI) at TRBM-2026-05-05. Audit logs are approved as the payer''s audit source.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-011.pdf'),
  ('DR-2026-013', 'decision_record', 'Decision Record DR-2026-013: Auto Loader', DATE '2026-06-02', 'TRBM-2026-06-02', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-013.md', array('TRB-2026-013'), current_timestamp(), 'Decision record: Auto Loader approved (scope: PHI) at TRBM-2026-06-02. Auto Loader is approved as the standard incremental ingestion path for claims and eligibility.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-013.pdf'),
  ('DR-2026-014', 'decision_record', 'Decision Record DR-2026-014: Lakeflow Declarative Pipelines (DLT)', DATE '2026-06-02', 'TRBM-2026-06-02', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-014.md', array('TRB-2026-014'), current_timestamp(), 'Decision record: Lakeflow Declarative Pipelines (DLT) approved (scope: PHI) at TRBM-2026-06-02. DLT is approved as the enterprise standard for building and curating trusted claims and member tables.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-014.pdf'),
  ('DR-2026-015', 'decision_record', 'Decision Record DR-2026-015: Lakeflow Jobs (Workflows)', DATE '2026-06-02', 'TRBM-2026-06-02', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-015.md', array('TRB-2026-015'), current_timestamp(), 'Decision record: Lakeflow Jobs (Workflows) approved (scope: PHI) at TRBM-2026-06-02. Workflows is approved as the enterprise standard for all scheduled and multi-step workloads.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-015.pdf'),
  ('DR-2026-016', 'decision_record', 'Decision Record DR-2026-016: Delta Lake', DATE '2026-06-16', 'TRBM-2026-06-16', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-016.md', array('TRB-2026-016'), current_timestamp(), 'Decision record: Delta Lake approved (scope: PHI) at TRBM-2026-06-16. Delta Lake is approved as the default table format.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-016.pdf'),
  ('DR-2026-018', 'decision_record', 'Decision Record DR-2026-018: Databricks SQL', DATE '2026-06-16', 'TRBM-2026-06-16', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-018.md', array('TRB-2026-018'), current_timestamp(), 'Decision record: Databricks SQL approved (scope: PHI) at TRBM-2026-06-16. Databricks SQL is approved as the enterprise serving layer for BI and analytics.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-018.pdf'),
  ('DR-2026-019', 'decision_record', 'Decision Record DR-2026-019: AI/BI Dashboards', DATE '2026-06-16', 'TRBM-2026-06-16', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-019.md', array('TRB-2026-019'), current_timestamp(), 'Decision record: AI/BI Dashboards approved (scope: PHI) at TRBM-2026-06-16. AI/BI Dashboards are approved for internal governance and reporting with PHI filters.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-019.pdf'),
  ('DR-2026-021', 'decision_record', 'Decision Record DR-2026-021: MLflow', DATE '2026-06-16', 'TRBM-2026-06-16', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-021.md', array('TRB-2026-021'), current_timestamp(), 'Decision record: MLflow approved (scope: PHI) at TRBM-2026-06-16. MLflow is approved as the enterprise model registry and lifecycle system.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-021.pdf'),
  ('DR-2026-025', 'decision_record', 'Decision Record DR-2026-025: Secure Cluster Connectivity (NPIP)', DATE '2026-04-21', 'TRBM-2026-04-21', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-025.md', array('TRB-2026-025'), current_timestamp(), 'Decision record: Secure Cluster Connectivity (NPIP) approved (scope: PHI) at TRBM-2026-04-21. Secure Cluster Connectivity is approved and required for all production PHI workloads.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-025.pdf'),
  ('DR-2026-026', 'decision_record', 'Decision Record DR-2026-026: PrivateLink (front-end & back-end)', DATE '2026-04-21', 'TRBM-2026-04-21', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-026.md', array('TRB-2026-026'), current_timestamp(), 'Decision record: PrivateLink (front-end & back-end) approved (scope: PHI) at TRBM-2026-04-21. PrivateLink is approved as a core requirement for the payer''s PHI environment.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-026.pdf'),
  ('DR-2026-027', 'decision_record', 'Decision Record DR-2026-027: Customer-managed keys (CMK)', DATE '2026-04-21', 'TRBM-2026-04-21', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-027.md', array('TRB-2026-027'), current_timestamp(), 'Decision record: Customer-managed keys (CMK) approved (scope: PHI) at TRBM-2026-04-21. Customer-managed keys are approved and required for all PHI data at rest.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-027.pdf'),
  ('DR-2026-028', 'decision_record', 'Decision Record DR-2026-028: Compliance security profile', DATE '2026-04-21', 'TRBM-2026-04-21', '/Volumes/serverless_stable_swv01_catalog/trb/corpus/DR-2026-028.md', array('TRB-2026-028'), current_timestamp(), 'Decision record: Compliance security profile approved (scope: PHI) at TRBM-2026-04-21. The Compliance Security Profile is approved and required for all PHI workloads.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/DR-2026-028.pdf'),
