  ('RA-TRB-2026-005', 'risk_assessment', 'Security & Privacy (HIPAA) Risk Assessment – Genie One', DATE '2026-07-21', NULL, '/Volumes/serverless_stable_swv01_catalog/trb/corpus/RA-TRB-2026-005.md', array('TRB-2026-005'), current_timestamp(), 'Security and privacy risk assessment for Genie One: data access under user UC permissions, row filters and masks, audit through system tables, small-cell suppression. Open items pending account-team confirmation.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/RA-TRB-2026-005.pdf'),
  ('RA-TRB-2026-007', 'risk_assessment', 'Security & Privacy (HIPAA) Risk Assessment – Mode: Databricks-to-Open', DATE '2026-08-11', NULL, '/Volumes/serverless_stable_swv01_catalog/trb/corpus/RA-TRB-2026-007.md', array('TRB-2026-007'), current_timestamp(), 'Risk assessment for Databricks-to-Open sharing: bearer-token and OIDC recipient auth, token lifetime, recipient IP access lists, BAA before PHI, and share-access audit.', '/Volumes/serverless_stable_swv01_catalog/trb/corpus_pdf/RA-TRB-2026-007.pdf');
